let packageInspectionSerial=0;
async function inspectDemoSppkg(file){
  if(!file||!/^.+\.sppkg$/i.test(file.name)||!Number.isFinite(file.size)||file.size<=0||file.size>10000000)throw Error('Choisissez un package .sppkg de 10 Mo maximum.');
  if(typeof JSZip==='undefined'||typeof DOMParser==='undefined')throw Error('La lecture locale du package est indisponible.');
  let archive;try{archive=await JSZip.loadAsync(await file.arrayBuffer())}catch{throw Error('Impossible de lire cette archive de package.')}
  const entries=Object.values(archive.files||{}),manifests=entries.filter(entry=>!entry.dir&&entry.name.toLowerCase()==='appmanifest.xml');
  if(entries.length>2000||manifests.length!==1)throw Error('Le manifeste racine unique est introuvable ou le package contient trop de fichiers.');
  const entry=manifests[0],size=entry._data?.uncompressedSize;
  if(!Number.isInteger(size)||size<1||size>262144)throw Error('La taille du manifeste dépasse les limites de la démonstration.');
  let xml;try{xml=await entry.async('string')}catch{throw Error('Impossible de lire le manifeste du package.')}
  if(xml.length>262144||/<!\s*(?:DOCTYPE|ENTITY)\b/i.test(xml))throw Error('Le manifeste contient des déclarations non prises en charge.');
  const document=new DOMParser().parseFromString(xml,'application/xml'),root=document.documentElement;
  if(document.getElementsByTagName('parsererror').length||root?.localName!=='App'||String(root.getAttribute('IsClientSideSolution')||'').toLowerCase()!=='true')throw Error('Ce manifeste ne décrit pas une solution SPFx reconnue.');
  const name=String(root.getAttribute('Name')||'').trim(),title=String(root.getElementsByTagNameNS('*','Title')[0]?.textContent||'').trim(),version=String(root.getAttribute('Version')||'').trim();
  const displayTitle=title&&!/^\$Resources:/i.test(title)?title:name;
  if(!displayTitle||displayTitle.length>255||(version&&!/^\d+\.\d+\.\d+\.\d+$/.test(version)))throw Error('Le titre ou la version du manifeste est invalide.');
  const componentFiles=entries.filter(item=>!item.dir&&/^[^/]+\/(?:WebPart|AdaptiveCardExtension|Application|Extension|Library|CopilotComponent)_[^/]+\.xml$/i.test(item.name));
  const candidates=new Set();let incomplete=componentFiles.length>50,total=0;
  const addCandidate=value=>{if(typeof value!=='string'||!/^https?:\/\//i.test(value))return;const normalized=demoScriptSource(value);if(!normalized||candidates.size>=100){incomplete=true;return}candidates.add(normalized)};
  for(const componentFile of componentFiles.slice(0,50)){
    const length=componentFile._data?.uncompressedSize;if(!Number.isInteger(length)||length<1||length>262144||(total+=length)>1000000){incomplete=true;continue}
    try{const content=await componentFile.async('string');if(content.length>262144||/<!\s*(?:DOCTYPE|ENTITY)\b/i.test(content)){incomplete=true;continue}const parsed=new DOMParser().parseFromString(content,'application/xml'),components=parsed.getElementsByTagNameNS('*','ClientSideComponent');if(parsed.getElementsByTagName('parsererror').length||!components.length){incomplete=true;continue}for(const component of components){const manifest=JSON.parse(component.getAttribute('ComponentManifest')||'{}'),loader=manifest.loaderConfig||{};if(Array.isArray(loader.internalModuleBaseUrls))for(const value of loader.internalModuleBaseUrls)addCandidate(value);if(loader.scriptResources&&typeof loader.scriptResources==='object')for(const resource of Object.values(loader.scriptResources))if(resource?.type==='path')addCandidate(resource.path)}}catch{incomplete=true}
  }
  return {title:displayTitle,version,scriptSources:[...candidates],incomplete};
}
