function backupLinkEntries(item){const entries=[];if(!item||typeof item!=='object')return entries;for(const key of ['linkSettings','normalLinkSettings'])if(item[key])entries.push([key,item[key]]);if(Array.isArray(item.normalLinks))item.normalLinks.forEach((link,index)=>entries.push(['normalLinks:'+String(link?.id??index),link]));return entries}
