function contentTypeAncestry(type,list){
  const nodes=[],seen=new Set();let current=type,problem='';
  while(current){
    if(seen.has(current)){problem='Cycle détecté dans les relations locales.';break}
    seen.add(current);nodes.push({name:current.name,index:list.indexOf(current)});
    const name=current.parent;if(!name)break;
    const parent=list.find(item=>item.name===name&&(!current.parentCategory||item.category===current.parentCategory));
    if(parent){current=parent;continue}
    if(isBuiltinContentType(name)){
      let builtin=name;const known={Document:'Élément',Dossier:'Élément','Élément':'Système'};
      while(builtin){nodes.push({name:builtin,index:-1});if(builtin==='Système')break;if(!known[builtin]){problem='L’ascendance de ce type intégré n’est pas disponible dans cette démonstration.';break}builtin=known[builtin]}
    }else{nodes.push({name,index:-1});problem='Un parent n’est pas disponible dans cette démonstration.'}
    break;
  }
  return {nodes:nodes.reverse(),problem};
}
function contentTypeAncestryPanel(type,list){
  if(!state.contentTypeAncestry)return '';
  const result=contentTypeAncestry(type,list);
  return `<div class="sp-nav-overlay"><aside class="sp-nav-editor sp-content-ancestry" role="dialog" aria-modal="true" aria-labelledby="content-ancestry-title"><div class="sp-panel-head"><h2 id="content-ancestry-title">Relation parentale</h2><button data-content-type="ancestry-close" aria-label="Fermer">×</button></div><p>Reconstruction de démonstration : seules les relations locales et quelques types intégrés observés sont disponibles.</p><ol>${result.nodes.map(node=>`<li>${node.index>=0&&node.index!==state.contentTypeSelected?`<button data-content-type="open" data-index="${node.index}">${esc(node.name)}</button>`:`<span${node.index===state.contentTypeSelected?' aria-current="true"':''}>${esc(node.name)}</span>`}</li>`).join('')}</ol>${result.problem?`<p role="status">${esc(result.problem)}</p>`:''}<button data-content-type="ancestry-close">Fermer</button></aside></div>`;
}
function contentTypeIsPublished(type){return !!type.published&&type.publishedActive!==false}
function contentTypeLocalColumnKind(type){const kinds={'Une seule ligne de texte':'text','Plusieurs lignes de texte':'multiline','Nombre':'number','Date et heure':'datetime','Oui/Non':'boolean','Choix':'choice'};return Object.hasOwn(kinds,type)?kinds[type]:null}
function contentTypeMergeChoices(...groups){const seen=new Set(),result=[];for(const group of groups)for(const value of Array.isArray(group)?group:[]){const text=String(value).trim(),key=text.toLocaleLowerCase('fr');if(text&&!seen.has(key)){seen.add(key);result.push(text)}}return result}
function saveContentTypePublication(list,index,operation,snapshot,family){const previousTypes=db.adminContentTypes,previousSites=db.sites,nextTypes=structuredClone(list),type=nextTypes[index],oldSnapshot=type.publishedSnapshot;let id=type.publicationId||crypto.randomUUID(),suffix=1;while(nextTypes.some((item,i)=>i!==index&&item.publicationId===id))id=id.replace(/-copy-\d+$/,'')+'-copy-'+suffix++;type.publicationId=id;const date=new Date().toISOString().slice(0,10);if(operation==='unpublish')type.publishedActive=false;else{type.published=date;type.publishedActive=true;type.publishedSnapshot=snapshot;type.publishedFamily=family}const nextSites=structuredClone(previousSites);if(operation!=='publish')for(const site of nextSites)for(const target of Array.isArray(site.lists)?site.lists:[]){if(!Array.isArray(target.hubTypeCopies))continue;for(const copy of target.hubTypeCopies){const matches=copy.sourceId===id||(!copy.sourceId&&oldSnapshot&&JSON.stringify(copy.snapshot)===JSON.stringify(oldSnapshot));if(!matches||copy.subscribed===false)continue;copy.sourceId=id;if(operation==='unpublish'){copy.subscribed=false;continue}if(family!=='list'){target.hubTypeWarnings=[...new Set([...(target.hubTypeWarnings||[]),'La famille publiée n’est plus reconnue comme liste ; la copie locale est conservée.'])];continue}copy.name=snapshot.name;copy.published=date;copy.snapshot=structuredClone(snapshot);copy.subscribed=true;target.columns=Array.isArray(target.columns)?target.columns:[];const byName=new Map(target.columns.map(column=>[String(column.name||'').toLocaleLowerCase('fr'),column])),used=new Set(target.columns.map(column=>column.id)),warnings=[...(target.hubTypeWarnings||[])];for(const column of target.columns){const original=String(column.hubOriginalName||'').toLocaleLowerCase('fr');if(original&&!byName.has(original))byName.set(original,column)}for(const column of snapshot.columns){const name=String(column.name||'').trim(),key=name.toLocaleLowerCase('fr'),kind=contentTypeLocalColumnKind(column.type);if(!name||['titre','nom'].includes(key))continue;if(!kind){warnings.push(name+' : type de colonne non pris en charge');continue}const existing=byName.get(key);if(existing){if(existing.type!==kind)warnings.push(name+' : types incompatibles');else if(kind==='choice')existing.choices=contentTypeMergeChoices(existing.choices,column.choices);continue}let columnId=crypto.randomUUID(),columnSuffix=1;while(used.has(columnId))columnId=columnId.replace(/-copy-\d+$/,'')+'-copy-'+columnSuffix++;used.add(columnId);const created={id:columnId,name,type:kind,description:'',required:false,hubManaged:true,hubOriginalName:name,defaultValue:'',...(kind==='choice'?{choices:contentTypeMergeChoices(column.choices)}:{})};if(column.required&&Array.isArray(target.rows)&&target.rows.length)warnings.push(name+' : caractère obligatoire à vérifier pour les éléments existants');target.columns.push(created);byName.set(key,created)}target.hubTypeWarnings=[...new Set(warnings)]}}db.adminContentTypes=nextTypes;db.sites=nextSites;try{save();return true}catch{if(previousTypes===undefined)delete db.adminContentTypes;else db.adminContentTypes=previousTypes;db.sites=previousSites;notice('Impossible d’enregistrer cette publication locale.');return false}}
function contentTypePublicationFamily(type,list){const seen=new Set();let current=type;while(current){if(seen.has(current))return 'unknown';seen.add(current);if(current.parent==='Document'&&(!current.parentCategory||current.parentCategory==='Types de contenu de document'))return 'document';if(current.parent==='Élément'&&(!current.parentCategory||current.parentCategory==='Types de contenu de liste'))return 'list';current=list.find(item=>item!==current&&item.name===current.parent&&(!current.parentCategory||item.category===current.parentCategory))}return 'unknown'}
function contentTypePublicationSnapshot(type,list){return {name:type.name||'',description:type.description||'',category:type.category||'',parent:type.parent||'',columns:contentTypeColumns(type,list).map(column=>({name:column.name||'',type:column.type||'',required:!!column.required,source:column.source||'',...(column.type==='Choix'?{choices:contentTypeMergeChoices(column.choices)}:{})}))}}
function contentTypePublicationSummary(type,list){const snapshot=type.publishedSnapshot;if(!snapshot||!Array.isArray(snapshot.columns))return type.published?'<p>La définition de la dernière publication locale est indisponible pour cette fiche ancienne.</p>':'';const changed=JSON.stringify(snapshot)!==JSON.stringify(contentTypePublicationSnapshot(type,list));return `<p>Modifications depuis la dernière publication simulée : ${changed?'Oui':'Non'}</p><details><summary>Dernière définition publiée dans la simulation</summary><p>Nom : ${esc(snapshot.name)}<br>Catégorie : ${esc(snapshot.category)}<br>Parent : ${esc(snapshot.parent)}<br>Description : ${esc(snapshot.description||'Aucune')}</p><ul>${snapshot.columns.map(column=>`<li>${esc(column.name)} · ${esc(column.type)} · ${column.required?'Obligatoire':'Facultatif'} · ${esc(column.source)}</li>`).join('')}</ul></details>`}
function contentTypePublicationPanel(type){if(!state.contentTypePublishing)return '';const published=contentTypeIsPublished(type);return `<div class="sp-nav-overlay"><aside class="sp-nav-editor" id="content-publication-panel" role="dialog" aria-modal="true" aria-labelledby="content-publication-title" tabindex="-1"><div class="sp-panel-head"><h2 id="content-publication-title">Gérer la publication</h2><button type="button" data-content-type="publication-close" aria-label="Fermer">×</button></div><p>Simulation locale : aucune publication ni modification de sites Microsoft 365.</p><form id="content-publication-form"><fieldset><legend>Action de publication</legend>${published?'<label class="sp-check"><input type="radio" name="operation" value="republish" checked> Republier</label><label class="sp-check"><input type="radio" name="operation" value="unpublish"> Annuler la publication</label>':'<label class="sp-check"><input type="radio" name="operation" value="publish" checked> Publier</label>'}</fieldset><p id="content-publication-error" role="alert"></p><button class="sp-primary" type="submit">Enregistrer</button> <button type="button" data-content-type="publication-close">Annuler</button></form></aside></div>`}
