function queryConditionMarkup(condition={}){
  return `<div class="sp-query-condition"><label class="sp-field">Type de condition<select data-condition-type><option value="exact" ${!condition.conditionType||condition.conditionType==='exact'?'selected':''}>La requête correspond exactement au mot-clé</option><option value="action" ${condition.conditionType==='action'?'selected':''}>La requête contient un terme d’action</option><option value="advanced" ${condition.conditionType==='advanced'?'selected':''}>Correspondance de texte de la requête avancée</option></select></label><label class="sp-field">Expressions<input data-condition-phrases maxlength="1000" value="${esc(condition.phrases||'')}"></label><fieldset data-condition-advanced ${condition.conditionType==='advanced'?'':'hidden'}><legend>Position de la correspondance</legend><label class="sp-check"><input type="checkbox" data-condition-exact ${condition.conditionType!=='advanced'||condition.matchExact?'checked':''}> La requête entière correspond exactement</label><label class="sp-check"><input type="checkbox" data-condition-start ${condition.matchStart?'checked':''}> Seul le début de la requête correspond</label><label class="sp-check"><input type="checkbox" data-condition-end ${condition.matchEnd?'checked':''}> Seule la fin de la requête correspond</label><p>Les variables de capture ne sont pas simulées.</p></fieldset><button type="button" data-condition-remove>Supprimer la condition</button></div>`;
}
function queryRulesForView(source,filter={},now=new Date()){
  const day=filter.date||[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-'),text=String(filter.text||'').trim().toLocaleLowerCase('fr');
  return (db.classicQueryRules||[]).filter(rule=>{
    if(source!=='all'&&rule.source!=='all'&&rule.source!==source)return false;
    if(filter.date&&(!rule.active||(rule.start&&day<rule.start)||(rule.end&&day>rule.end)))return false;
    if(filter.mode==='query'&&text&&!queryRuleMatches(rule,text,day,source))return false;
    if(filter.mode==='promoted'&&text&&!String(rule.title||'').toLocaleLowerCase('fr').includes(text)&&!String(rule.url||'').toLocaleLowerCase('fr').includes(text))return false;
    if(filter.mode==='active'&&!rule.active||filter.mode==='inactive'&&rule.active)return false;
    if(filter.mode==='expired'&&(!rule.end||rule.end>=day))return false;
    if(filter.mode==='review'&&(!rule.review||rule.review>day))return false;
    if(filter.mode==='has-promoted'&&!rule.title)return false;
    return true;
  });
}
