function localQueryBuilder(){return `<div id="local-query-builder" class="sp-query-overlay" hidden><div class="sp-query-dialog" role="dialog" aria-modal="true" aria-labelledby="local-query-title"><h2 id="local-query-title">Créer votre requête</h2><p class="sp-card-note">Générateur simplifié de démonstration : aucun service externe n’est interrogé.</p><div class="sp-query-grid"><div><h3>Concepts de base</h3><label class="sp-field">Filtre de propriétés<select id="local-query-property"><option value="">Sélectionner une propriété</option><option>Author</option><option>ContentType</option><option>FileType</option><option>LastModifiedTime</option><option>contentclass</option></select></label><label class="sp-field">Valeur manuelle<input id="local-query-value" maxlength="200"></label><button type="button" id="local-query-add">Ajouter un filtre de propriétés</button><label class="sp-field">Texte de requête<textarea id="local-query-text" maxlength="1000"></textarea></label><label class="sp-field">Terme pour l’aperçu<input id="local-query-term" maxlength="120"></label><button type="button" id="local-query-test">Tester la requête</button></div><div><h3>Aperçu des résultats de la recherche</h3><p>L’aperçu recherche uniquement le terme dans les noms des documents locaux ; il n’interprète pas la syntaxe de requête.</p><p id="local-query-preview" role="status">Aucun test effectué.</p></div></div><footer><button type="button" class="sp-primary" id="local-query-apply">OK</button> <button type="button" id="local-query-cancel">Annuler</button></footer></div></div>`}
