  if(['profiles','profiles-list','profile-new','profile-edit'].includes(state.classicFeature))return classicProfilesPage();
  if(state.classicFeature==='query-rule-edit'){
    const rule=(db.classicQueryRules||[]).find(item=>item.id===state.queryRuleId)||{},sources=resultSources();
    return `<div class="sp-classic-search"><button data-classic="query-rules">‹ Gérer les règles de requête</button><h1>${rule.id?'Modifier':'Nouvelle'} règle de requête</h1><p class="sp-callout">Règle fictive enregistrée localement ; elle ne modifie pas la recherche Microsoft 365.</p><form id="query-rule-form"><section><h2>Informations générales</h2><label class="sp-field">Nom de la règle<input name="name" required maxlength="120" value="${esc(rule.name||'')}"></label></section><section><h2>Contexte</h2><label class="sp-field">La requête porte sur ces sources<select name="source">${rule.id&&rule.source!=='all'&&!sources.some(source=>source.id===rule.source)?`<option value="${esc(rule.source)}" selected disabled>Origine supprimée — choisissez une autre origine</option>`:''}<option value="all">Toutes les sources</option>${sources.map(source=>`<option value="${esc(source.id)}" ${(rule.source||state.queryRuleSource)===source.id?'selected':''}>${esc(source.name)}</option>`).join('')}</select></label></section><section><h2>Conditions de la requête</h2><p>Les conditions sont alternatives. S’il n’y en a aucune, la règle s’applique à toutes les requêtes. Séparez les expressions par des points-virgules.</p><div id="query-conditions">${(Array.isArray(rule.conditions)?rule.conditions:(rule.id&&rule.phrases?[rule]:rule.id?[]:[{}])).map(queryConditionMarkup).join('')}</div><button type="button" id="query-condition-add">Ajouter une autre condition</button></section><section><h2>Actions</h2><h3>Résultat promu</h3><label class="sp-field">Titre<input name="title" maxlength="200" value="${esc(rule.title||'')}"></label><label class="sp-field">URL<input name="url" maxlength="2048" value="${esc(rule.url||'')}"></label><label class="sp-check"><input type="checkbox" name="banner" ${rule.banner?'checked':''}> Afficher l’URL sous forme de bannière plutôt que de lien hypertexte</label><label class="sp-field">Description<textarea name="description" maxlength="500">${esc(rule.description||'')}</textarea></label><p>Les blocs de résultats et la modification du classement restent à reproduire.</p></section><section><h2>Publication</h2><label class="sp-check"><input type="checkbox" name="active" ${rule.active!==false?'checked':''}> Est actif</label><label class="sp-field">Date de début<input type="date" name="start" value="${esc(rule.start||'')}"></label><label class="sp-field">Date de fin<input type="date" name="end" value="${esc(rule.end||'')}"></label><label class="sp-field">Vérifié le<input type="date" name="review" value="${esc(rule.review||'')}"></label><label class="sp-field">Contact fictif<input name="contact" maxlength="200" value="${esc(rule.contact||'')}"></label></section><p id="query-rule-error" role="alert"></p><button class="sp-primary">Enregistrer</button> <button type="button" data-classic="query-rules">Annuler</button></form></div>`;
  }
  if(state.classicFeature==='query-rules'){
    const source=state.queryRuleSource||'',filter=state.queryRuleFilter||{},rules=queryRulesForView(source,filter);
    return `<div class="sp-classic-search"><button data-classic="search">‹ Rechercher</button><h1>Gérer les règles de requête</h1><p>Utilisez des règles de requête pour promouvoir des résultats et ajuster la recherche.</p><p class="sp-callout">Règles de démonstration locales : les résultats promus des conditions simples sont affichés dans la recherche du site ; les règles fournies par SharePoint ne sont pas chargées.</p><label>Pour quel contexte voulez-vous configurer des règles ? <select id="query-rule-source"><option value="">Sélectionner une origine des résultats...</option>${resultSources().map(item=>`<option value="${esc(item.id)}" ${source===item.id?'selected':''}>${esc(item.name)}${item.builtin?' (service)':''}</option>`).join('')}<option value="all" ${source==='all'?'selected':''}>Toutes les sources</option></select></label><p><button data-query-rule="new">＋ Nouvelle règle de requête</button></p><form id="query-rule-filter"><label>Filtrer <select name="mode"><option value="query" ${(!filter.mode||filter.mode==='query')?'selected':''}>Tester une requête...</option>${[['promoted','Le résultat promu contient...'],['active','Actif'],['inactive','Inactif'],['review','Révision nécessaire'],['expired','Expiré'],['has-promoted','Ajoute les résultats promus']].map(([value,label])=>`<option value="${value}" ${filter.mode===value?'selected':''}>${label}</option>`).join('')}<option disabled>Ajoute des blocs de résultats</option><option disabled>Modifie les résultats classés</option></select></label> <label>Texte <input name="text" value="${esc(filter.text||'')}" ${source?'':'disabled'}></label> <label>Date <input type="date" name="date" value="${esc(filter.date||'')}"></label> <button ${source?'':'disabled'}>Filtrer</button></form><p class="sp-card-note">Le test utilise uniquement les conditions simples des règles locales.</p>${!source?'<p>Sélectionnez une source ci-dessus pour afficher les règles qui s’appliquent aux requêtes de cette source.</p>':`<div class="sp-table"><table><thead><tr><th>Nom</th><th>Modifié</th><th>Conditions</th><th>Actions</th><th>État</th><th></th></tr></thead><tbody>${rules.map(rule=>`<tr><td>${esc(rule.name)}</td><td>${esc(rule.modified)}</td><td>${esc(Array.isArray(rule.conditions)?rule.conditions.map(c=>c.phrases).join(' · ')||'Toutes les requêtes':rule.phrases||'Toutes les requêtes')}</td><td>${esc(rule.title||'Aucun résultat promu')}</td><td>${rule.active?'Actif':'Inactif'}</td><td><button data-query-rule="edit" data-id="${esc(rule.id)}">Modifier</button> <button data-query-rule="delete" data-id="${esc(rule.id)}">Supprimer</button></td></tr>`).join('')}</tbody></table>${rules.length?'':'<p>Aucune règle locale pour cette source.</p>'}</div>`}</div>`;
  }
  if(state.classicFeature==='result-source-edit'){const selected=(db.classicResultSources||[]).find(source=>source.id===state.resultSourceId)||{},editing=!!selected.id;return `<div class="sp-classic-search"><button data-classic="result-sources">‹ Gérer les origines des résultats</button><h1>${editing?'Modifier':'Ajouter'} une origine des résultats</h1><p class="sp-callout">Origine fictive locale : aucune source externe n’est interrogée.</p><form id="result-source-form"><section><h2>Informations générales</h2><label class="sp-field">Nom<input name="name" maxlength="120" required value="${esc(selected.name||'')}"></label><label class="sp-field">Description<textarea name="description" maxlength="500">${esc(selected.description||'')}</textarea></label></section><section><h2>Protocole</h2><p>La recherche fédérée hybride a été mise hors service ; les protocoles distants ne sont plus disponibles.</p><label><input type="radio" checked disabled> SharePoint local</label><p>SharePoint distant et OpenSearch sont indisponibles dans la simulation.</p></section><section><h2>Type</h2><label class="sp-check"><input type="radio" name="type" value="sharepoint" ${selected.type!=='people'?'checked':''}> Résultats de la recherche SharePoint</label><label class="sp-check"><input type="radio" name="type" value="people" ${selected.type==='people'?'checked':''}> Résultats de la recherche de personnes</label></section><section><h2>Résultats de la recherche</h2><label class="sp-check"><input type="checkbox" name="noPartial" ${selected.noPartial?'checked':''}> Ne pas afficher les résultats de recherche partiels</label></section><section><h2>Transformation de requête</h2><label class="sp-field">Transformation de requête<input name="query" maxlength="1000" required value="${esc(selected.query||'{searchTerms}')}"></label><button type="button" id="local-query-open">Lancer le Générateur de requêtes</button>${localQueryBuilder()}</section><section><h2>Informations d’identification</h2><p>Authentification par défaut simulée.</p></section><p id="result-source-error" role="alert"></p><button class="sp-primary" type="submit">Enregistrer</button> <button type="button" data-classic="result-sources">Annuler</button></form></div>`}
