  if(state.classicFeature==='search-center'){const settings=db.classicSearchCenter||{};return `<div class="sp-classic-search"><button data-classic="search">‹ Rechercher</button><h1>Paramètres du centre de recherche</h1><p class="sp-callout">Réglages de démonstration locaux : aucune recherche Microsoft 365 n’est modifiée.</p><form id="search-center-form"><div class="sp-record-row"><div><h2>Entrez une URL pour le centre de recherche global</h2><p>Ce paramètre indique au système de recherche l’emplacement du centre de recherche par défaut.</p></div><label class="sp-field">URL du centre de recherche<input name="url" type="url" maxlength="2048" required value="${esc(settings.url||'https://demo.invalid/search/Pages')}"><small>Exemple : http://companyportal/searchcenter/pages</small></label></div><div class="sp-record-row"><div><h2>Chargement des résultats de la recherche</h2><p>Les résultats peuvent être demandés après l’affichage de la page ou pendant son chargement. Le chargement synchrone présente des risques de sécurité.</p></div><fieldset><legend class="sr-only">Chargement des résultats de la recherche</legend><label class="sp-check"><input type="radio" name="mode" value="async" ${settings.mode!=='both'?'checked':''}> Asynchrone uniquement</label><label class="sp-check"><input type="radio" name="mode" value="both" ${settings.mode==='both'?'checked':''}> Autoriser les deux</label></fieldset></div><p id="search-center-error" role="alert"></p><button class="sp-primary" type="submit">OK</button> <button type="button" data-classic="search">Annuler</button></form></div>`}
