  if(state.page==='Admin onedrive-accounts'){const rows=oneDriveReportRows(),sort=state.oneDriveReportSort||'account',direction=state.oneDriveReportDirection==='desc'?'descending':'ascending',header=(key,label)=>`<th aria-sort="${sort===key?direction:'none'}"><button type="button" data-onedrive-sort="${key}">${label} ${sort===key?(direction==='ascending'?'↑':'↓'):''}</button></th>`;return `<h1>Comptes OneDrive</h1><p>Utilisez cette page pour afficher des rapports hebdomadaires sur les comptes OneDrive sans licence au sein de votre organisation.</p><p class="sp-callout">Les données et le rapport ci-dessous sont fictifs ; aucun compte réel n’est chargé.</p><h2>Comptes OneDrive sans licence</h2><p>Rapport de démonstration · ${rows.length} compte(s) affiché(s) sur 30</p><div class="sp-admin-commands"><button data-admin-content="export-onedrive">Télécharger le rapport CSV</button><input id="onedrive-search" placeholder="Rechercher" aria-label="Rechercher un compte" value="${esc(state.oneDriveReportQuery||'')}"><label>État <select id="onedrive-status"><option value="all">Tous</option><option value="Sans licence" ${state.oneDriveReportStatus==='Sans licence'?'selected':''}>Sans licence</option><option value="Archivé" ${state.oneDriveReportStatus==='Archivé'?'selected':''}>Archivé</option></select></label></div><div class="sp-table"><table><thead><tr>${header('account','Compte')}${header('storage','Stockage (Go)')}${header('status','État')}</tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.account)}</td><td>${esc(row.storage)}</td><td>${esc(row.status)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p>Aucun compte ne correspond aux filtres.</p>'}</div>`}
