function fileScanMatches(scan,filters,query){
  if(query&&![scan.path,scan.tag,scan.scanStatus,scan.readiness].some(value=>String(value||'').toLocaleLowerCase('fr').includes(query)))return false;
  if(!filters)return true;const f=filters,lower=s=>String(s||'').toLocaleLowerCase('fr');
  if(f.tag&&!lower(scan.tag).includes(lower(f.tag)))return false;if(f.readiness?.length&&!f.readiness.includes(scan.readiness))return false;if(f.scanStatus?.length&&!f.scanStatus.includes(scan.scanStatus))return false;
  if(f.dateMin&&(!scan.modified||scan.modified<f.dateMin)||f.dateMax&&(!scan.modified||scan.modified>f.dateMax))return false;
  const count=scan.files===null||scan.folders===null?null:scan.files+scan.folders;
  for(const [value,min,max] of [[scan.size,f.sizeMin,f.sizeMax],[count,f.countMin,f.countMax]]){if(min!==''&&min!=null&&(value===null||value<Number(min)))return false;if(max!==''&&max!=null&&(value===null||value>Number(max)))return false}
  if(f.pathMode==='under'&&(scan.pathLength===null||scan.pathLength>=Number(f.pathLength)))return false;if(f.pathMode==='over'&&(scan.pathLength===null||scan.pathLength<=Number(f.pathLength)))return false;return true;
}
function downloadFileScanReport(){
  const query=(state.fileMigrationQuery||'').toLocaleLowerCase('fr'),scans=(db.adminFileScans||demoFileScans()).filter(scan=>fileScanMatches(scan,state.fileMigrationFilters,query));
  const rows=[['Chemin de source fictif','Balises','Préparation à la migration','État de l’analyse','Taille (Go)','Nombre de fichiers','Nombre de dossiers','Longueur maximale du chemin','Date de modification fictive','Créé le'],...scans.map(scan=>[scan.path,scan.tag,scan.readiness,scan.scanStatus,scan.size,scan.files,scan.folders,scan.pathLength,scan.modified,scan.created])];
  const csv='\ufeff'+rows.map(row=>row.map(value=>{let text=String(value??'');if(/^[\s\u0000-\u001f]*[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}).join(';')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='rapport-analyses-fictives.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function parseMigrationCsvRecords(input){
  const text=String(input||'').replace(/^\uFEFF/,'');
  if(text.length>1000000)throw Error('Le fichier dépasse la limite locale de 1 Mo.');
  const rows=[];let row=[],field='',quoted=false,closed=false;
  for(let i=0;i<text.length;i++){
    const char=text[i];
    if(quoted){if(char==='"'){if(text[i+1]==='"'){field+='"';i++}else{quoted=false;closed=true}}else field+=char;continue}
    if(closed&&char!==','&&char!=='\r'&&char!=='\n')throw Error('Le fichier CSV contient des guillemets invalides.');
    if(char==='"'){if(field)throw Error('Le fichier CSV contient des guillemets invalides.');quoted=true;continue}
    if(char===','||char==='\r'||char==='\n'){row.push(field);field='';closed=false;if(char!==','){if(char==='\r'&&text[i+1]==='\n')i++;if(row.some(value=>value.trim()))rows.push(row);row=[]}continue}
    field+=char;
  }
  if(quoted)throw Error('Le fichier CSV contient des guillemets non fermés.');
  row.push(field);if(row.some(value=>value.trim()))rows.push(row);
  return rows;
}
function parseFileMigrationCsv(input){
  const rows=parseMigrationCsvRecords(input);
  const header=rows[0]?.[0]?.trim().toLowerCase()==='filesharepath';if(header)rows.shift();
  if(!rows.length||rows.length>1000)throw Error('Ajoutez entre 1 et 1 000 tâches fictives.');
  return rows.map((values,index)=>{
    if(values.length!==6)throw Error(`Ligne ${index+1+(header?1:0)} : six colonnes sont nécessaires.`);
    const [path,unused1,unused2,destination,library,folder]=values.map(value=>value.trim());
    let url;try{url=new URL(destination)}catch{}
    const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(destination);
    if(!/^\\\\[^\\\r\n]+\\[^\\\r\n]+/.test(path)||path.length>300||unused1||unused2||(!email&&(!url||!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash))||destination.length>300||!library||library.length>120||folder.length>300||/[\r\n]/.test(library+folder))throw Error(`Ligne ${index+1+(header?1:0)} : vérifiez la source, les colonnes vides et la destination.`);
    const name=(path.split('\\').filter(Boolean).at(-1)||'Tâche locale').slice(0,120);
    return {name,source:'Partages de fichiers',path,destination,destinationType:email?'OneDrive':'SharePoint',destinationLibrary:library,destinationFolder:folder,status:'Brouillon local',progress:0};
  });
}
function normalizeFileScanPath(path){return String(path||'').replace(/\\+$/,'').toLocaleLowerCase('fr')}
function parseFileScanCsv(input,existing){
  const rows=parseMigrationCsvRecords(input);
  const heading=rows[0]?.length===1&&['sourcepath','file share path','filesharepath','source path','chemin d’accès de la source'].includes(rows[0][0].trim().toLocaleLowerCase('fr'));if(heading)rows.shift();
  if(!rows.length||rows.length>1000)throw Error('Ajoutez entre 1 et 1 000 chemins fictifs.');
  const known=new Set((existing||[]).map(scan=>normalizeFileScanPath(scan.path)));
  return rows.map((row,index)=>{
    const line=index+1+(heading?1:0),path=row[0]?.trim()||'';
    if(row.length!==1||!/^\\\\[^\\\r\n]+\\[^\\\r\n]+/.test(path)||path.length>300)throw Error(`Ligne ${line} : saisissez un chemin réseau valide dans une seule colonne.`);
    const key=normalizeFileScanPath(path);if(known.has(key))throw Error(`Ligne ${line} : ce chemin figure déjà dans la liste ou dans le fichier.`);known.add(key);return path;
  });
}
