function parseDemoMigrationMappings(input){const lines=String(input||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);if(lines.length>100)throw Error('Limite : 100 correspondances fictives.');const seen=new Set();return lines.map((line,index)=>{const parts=line.split(';').map(value=>value.trim()),source=parts[0]||'',target=parts[1]||'',key=source.toLocaleLowerCase('fr'),isGroup=demoGroups.some(group=>group.name===target);if(parts.length!==2||!/^[a-z0-9._+-]{1,80}@[a-z0-9.-]+\.(?:example|invalid)$/i.test(source)||(!people.includes(target)&&!isGroup)||seen.has(key))throw Error(`Ligne ${index+1} : utilisez une adresse fictive distincte (.example ou .invalid) et une personne ou un groupe proposé.`);seen.add(key);return {source,target,...(isGroup?{isGroup:true}:{})}})}
